const DEFAULT_CENTER = { lat: 55.7558, lon: 37.6173 };
const DEFAULT_RADIUS = 1200;
const MIN_RADIUS = 200;
const MAX_RADIUS = 5000;
const PAGE = 10;

const TITLES = ["слепой двор","ржавая арка","фонарь без свидетелей","порог между домами","тихий карман города","место, где карта врёт","пустой угол","эхо переулка"];
const OMENS = ["найди знак, который смотрит не туда","досчитай до семи окон и сверни взгляд","заметь предмет, который будто забыли специально","не фотографируй первым — сначала посмотри","ищи отражение: стекло, вода, витрина","остановись там, где шум внезапно провалится"];

const now = () => new Date().toISOString();
const uid = () => crypto.randomUUID();
const pick = a => a[Math.floor(Math.random() * a.length)];
const esc = v => String(v ?? "").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const urlEsc = v => String(v ?? "").replaceAll("&","&amp;");
const trim = (v,n) => String(v || "").trim().slice(0,n);
const normCallsign = v => String(v || "").trim().replace(/\s+/g," ").slice(0,32);
const hasLink = t => /(https?:\/\/|www\.|t\.me\/|telegram\.me\/|\.ru\b|\.com\b|\.net\b|\.org\b)/i.test(String(t || ""));
const point = (lat, lon) => ({ lat: Number(Number(lat).toFixed(6)), lon: Number(Number(lon).toFixed(6)) });
const validPoint = (lat, lon) => Number.isFinite(lat) && Number.isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
const hasHome = p => p && typeof p.base_lat === "number" && typeof p.base_lon === "number";
const registered = p => Boolean(p && p.callsign);
const bestPhoto = m => Array.isArray(m?.photo) && m.photo.length ? m.photo[m.photo.length - 1].file_id : null;
const msgText = m => m?.text ? m.text.trim() : "";

function dist(a,b){const R=6371000,la=a.lat*Math.PI/180,lb=b.lat*Math.PI/180,dx=(b.lat-a.lat)*Math.PI/180,dy=(b.lon-a.lon)*Math.PI/180,h=Math.sin(dx/2)**2+Math.cos(la)*Math.cos(lb)*Math.sin(dy/2)**2;return Math.round(R*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h)));}
function randomPoint(c,r){const a=Math.random()*Math.PI*2,d=Math.sqrt(Math.random())*r,E=6371000;return point(c.lat+(d*Math.cos(a)/E)*180/Math.PI,c.lon+(d*Math.sin(a)/(E*Math.cos(c.lat*Math.PI/180)))*180/Math.PI);}
const mapUrl = p => "https://www.google.com/maps?q="+p.lat+","+p.lon;
const routeUrl = (a,b) => "https://www.google.com/maps/dir/?api=1&origin="+a.lat+","+a.lon+"&destination="+b.lat+","+b.lon+"&travelmode=walking";
const eff = s => `${Number(s?.rating || 0) >= 0 ? "+" : ""}${Number(s?.rating || 0)} (${Number(s?.plus || 0)}+/ ${Number(s?.minus || 0)}-)`;

function commandOf(m){
  const t = msgText(m), low = t.toLowerCase();
  if (low.startsWith("/")) return low.split(/\s+/)[0].split("@")[0];
  if (low.includes("штаб")) return "/sethome";
  if (low.includes("сигнал") || low.includes("точка")) return "/point";
  if (low.includes("выход") || low.includes("маршрут")) return "/route";
  if (low.includes("досье") || low.includes("профиль")) return "/profile";
  if (low.includes("архив") || low.includes("история")) return "/history";
  if (low.includes("радиус")) return "/radius";
  if (low.includes("оперативники")) return "/operators";
  if (low.includes("кооперация")) return "/coops";
  if (low.includes("терминал") || low.includes("меню")) return "/menu";
  return "";
}
function replyKeyboard(){return {keyboard:[[{text:"⌂ Штаб"}],[{text:"◌ Сигнал"},{text:"⟡ Выход"}],[{text:"⊕ Оперативники"},{text:"⚭ Кооперация"}],[{text:"☾ Досье"},{text:"‡ Архив"}],[{text:"⛯ Радиус"},{text:"? Терминал"}]],resize_keyboard:true,is_persistent:true,input_field_placeholder:"WanderOS terminal"};}
const ik = rows => ({ inline_keyboard: rows });

async function tg(env, method, payload){const r=await fetch("https://api.telegram.org/bot"+env.TELEGRAM_BOT_TOKEN+"/"+method,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});let j;try{j=await r.json();}catch{j={ok:false,description:"bad json"};}if(!r.ok||j.ok!==true)console.error("Telegram API failed",method,r.status,JSON.stringify(j));return j;}
async function delMsg(env,chatId,messageId){if(!messageId)return;try{await tg(env,"deleteMessage",{chat_id:chatId,message_id:Number(messageId)});}catch{}}
async function remember(env,chatId,id,dir){if(!id)return;try{await env.DB.prepare(`INSERT OR IGNORE INTO ui_messages(chat_id,message_id,direction,created_at) VALUES(?,?,?,?)`).bind(String(chatId),Number(id),dir,now()).run();}catch{}}
async function known(env,chatId,limit=80){try{const r=await env.DB.prepare(`SELECT message_id FROM ui_messages WHERE chat_id=? ORDER BY created_at DESC LIMIT ?`).bind(String(chatId),limit).all();return (r.results||[]).map(x=>Number(x.message_id)).filter(Boolean);}catch{return[];}}
async function getUi(env,chatId){return await env.DB.prepare(`SELECT active_message_id FROM ui_state WHERE chat_id=?`).bind(String(chatId)).first();}
async function setUi(env,chatId,id){await env.DB.prepare(`INSERT INTO ui_state(chat_id,active_message_id,updated_at) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET active_message_id=excluded.active_message_id,updated_at=excluded.updated_at`).bind(String(chatId),Number(id),now()).run();}
async function clearUi(env,chatId){await env.DB.prepare(`INSERT INTO ui_state(chat_id,active_message_id,updated_at) VALUES(?,NULL,?) ON CONFLICT(chat_id) DO UPDATE SET active_message_id=NULL,updated_at=excluded.updated_at`).bind(String(chatId),now()).run();}
async function prune(env,chatId,keep){try{await env.DB.prepare(`DELETE FROM ui_messages WHERE chat_id=? AND message_id<>?`).bind(String(chatId),Number(keep||0)).run();}catch{}}
async function sendScreen(env,ctx,chatId,text,cleanup=[],opt={}){const ui=await getUi(env,chatId),old=ui?.active_message_id?Number(ui.active_message_id):null;let method="sendMessage",payload={chat_id:chatId,text,parse_mode:"HTML",disable_web_page_preview:true,reply_markup:opt.inline||replyKeyboard()};if(opt.photo){method="sendPhoto";payload={chat_id:chatId,photo:opt.photo,caption:text,parse_mode:"HTML",reply_markup:opt.inline||replyKeyboard()};}if(opt.video){method="sendVideo";payload={chat_id:chatId,video:opt.video,caption:text,parse_mode:"HTML",reply_markup:opt.inline||replyKeyboard()};}const sent=await tg(env,method,payload);if(sent.ok&&sent.result?.message_id){const id=Number(sent.result.message_id);await setUi(env,chatId,id);await remember(env,chatId,id,"bot");ctx.waitUntil((async()=>{for(const mid of [...new Set(cleanup.concat(old||[]).filter(Boolean).map(Number))])await delMsg(env,chatId,mid);await prune(env,chatId,id);})());}}

async function ensureDirectorySchema(env){try{await env.DB.prepare(`CREATE TABLE IF NOT EXISTS operator_reviews (reviewer_chat_id TEXT NOT NULL, target_chat_id TEXT NOT NULL, vote INTEGER NOT NULL CHECK(vote IN (-1, 1)), created_at TEXT NOT NULL, PRIMARY KEY(reviewer_chat_id, target_chat_id))`).run();await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_operator_reviews_target ON operator_reviews(target_chat_id)`).run();await env.DB.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS idx_operator_profiles_callsign_unique ON operator_profiles(callsign COLLATE NOCASE)`).run();await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_operator_profiles_callsign_search ON operator_profiles(callsign COLLATE NOCASE)`).run();}catch(e){console.error("ensureDirectorySchema",String(e));}}
async function reviewStats(env,target){await ensureDirectorySchema(env);const r=await env.DB.prepare(`SELECT COALESCE(SUM(vote),0) rating, COUNT(*) total, SUM(CASE WHEN vote=1 THEN 1 ELSE 0 END) plus, SUM(CASE WHEN vote=-1 THEN 1 ELSE 0 END) minus FROM operator_reviews WHERE target_chat_id=?`).bind(String(target)).first();return{rating:Number(r?.rating||0),total:Number(r?.total||0),plus:Number(r?.plus||0),minus:Number(r?.minus||0)};}
async function myReview(env,reviewer,target){await ensureDirectorySchema(env);return await env.DB.prepare(`SELECT vote FROM operator_reviews WHERE reviewer_chat_id=? AND target_chat_id=?`).bind(String(reviewer),String(target)).first();}
async function setReview(env,reviewer,target,vote){await ensureDirectorySchema(env);await env.DB.prepare(`INSERT INTO operator_reviews(reviewer_chat_id,target_chat_id,vote,created_at) VALUES(?,?,?,?)`).bind(String(reviewer),String(target),Number(vote),now()).run();}
async function callsignTaken(env,callsign,self=null){const r=await env.DB.prepare(`SELECT chat_id FROM operator_profiles WHERE callsign = ? COLLATE NOCASE LIMIT 1`).bind(callsign).first();return Boolean(r && String(r.chat_id)!==String(self||""));}

async function flowSet(env,chatId,mode,payload={}){await env.DB.prepare(`INSERT INTO flow_state(chat_id,mode,payload_json,updated_at) VALUES(?,?,?,?) ON CONFLICT(chat_id) DO UPDATE SET mode=excluded.mode,payload_json=excluded.payload_json,updated_at=excluded.updated_at`).bind(String(chatId),mode,JSON.stringify(payload),now()).run();}
async function flowGet(env,chatId){const r=await env.DB.prepare(`SELECT mode,payload_json FROM flow_state WHERE chat_id=?`).bind(String(chatId)).first();if(!r)return{mode:null,payload:{}};let p={};try{p=r.payload_json?JSON.parse(r.payload_json):{};}catch{}return{mode:r.mode,payload:p};}
async function flowClear(env,chatId){await env.DB.prepare(`INSERT INTO flow_state(chat_id,mode,payload_json,updated_at) VALUES(?,NULL,NULL,?) ON CONFLICT(chat_id) DO UPDATE SET mode=NULL,payload_json=NULL,updated_at=excluded.updated_at`).bind(String(chatId),now()).run();}
async function event(env,chatId,type,payload={}){try{await env.DB.prepare(`INSERT INTO events(chat_id,event_type,payload_json,created_at) VALUES(?,?,?,?)`).bind(String(chatId),type,JSON.stringify(payload),now()).run();}catch{}}

async function upsertUser(env,mOrCb){const msg=mOrCb.message?.chat?mOrCb.message:mOrCb;const chatId=String(msg.chat.id),from=mOrCb.from||msg.from||{},t=now();await env.DB.prepare(`INSERT INTO users(chat_id,username,first_name,language_code,created_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(chat_id) DO UPDATE SET username=excluded.username,first_name=excluded.first_name,language_code=excluded.language_code,updated_at=excluded.updated_at`).bind(chatId,from.username||null,from.first_name||null,from.language_code||null,t,t).run();await env.DB.prepare(`INSERT OR IGNORE INTO profiles(chat_id,city,radius_m,mood,created_at,updated_at) VALUES(?,'Москва',?,'liminal',?,?)`).bind(chatId,DEFAULT_RADIUS,t,t).run();return chatId;}
async function profile(env,chatId){return await env.DB.prepare(`SELECT u.chat_id,u.username,u.first_name,p.city,p.base_lat,p.base_lon,p.base_label,p.radius_m,p.mood,p.updated_at,op.callsign,op.age,op.sex,op.bio,op.photo_file_id,op.is_visible FROM users u JOIN profiles p ON p.chat_id=u.chat_id LEFT JOIN operator_profiles op ON op.chat_id=u.chat_id WHERE u.chat_id=?`).bind(String(chatId)).first();}
async function operator(env,chatId){return await env.DB.prepare(`SELECT op.*,u.username,u.first_name,p.base_lat,p.base_lon,p.radius_m FROM operator_profiles op JOIN users u ON u.chat_id=op.chat_id JOIN profiles p ON p.chat_id=op.chat_id WHERE op.chat_id=?`).bind(String(chatId)).first();}
async function setHome(env,chatId,lat,lon,label){const p=point(lat,lon);await env.DB.prepare(`UPDATE profiles SET base_lat=?,base_lon=?,base_label=?,updated_at=? WHERE chat_id=?`).bind(p.lat,p.lon,label||"штаб",now(),String(chatId)).run();return p;}
async function setRadius(env,chatId,r){await env.DB.prepare(`UPDATE profiles SET radius_m=?,updated_at=? WHERE chat_id=?`).bind(r,now(),String(chatId)).run();}
async function addRoute(env,chatId,kind,origin,target,r,title,omen){const id=uid(),map=mapUrl(target),route=routeUrl(origin,target);await env.DB.prepare(`INSERT INTO routes(id,chat_id,kind,origin_lat,origin_lon,target_lat,target_lon,radius_m,title,omen,map_url,route_url,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,String(chatId),kind,origin.lat,origin.lon,target.lat,target.lon,r,title,omen,map,route,now()).run();await env.DB.prepare(`INSERT OR IGNORE INTO trace_cards(route_id,chat_id,summary,updated_at) VALUES(?,?,NULL,?)`).bind(id,String(chatId),now()).run();return{id,map,route};}
async function routes(env,chatId,page=0){const r=await env.DB.prepare(`SELECT id,kind,target_lat,target_lon,title,omen,route_url,created_at FROM routes WHERE chat_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?`).bind(String(chatId),PAGE,page*PAGE).all();return r.results||[];}
async function countRoutes(env,chatId){const r=await env.DB.prepare(`SELECT COUNT(*) total FROM routes WHERE chat_id=?`).bind(String(chatId)).first();return Number(r?.total||0);}
async function countCoops(env,chatId){const r=await env.DB.prepare(`SELECT COUNT(*) total FROM cooperations WHERE status='accepted' AND (requester_chat_id=? OR target_chat_id=?)`).bind(String(chatId),String(chatId)).first();return Number(r?.total||0);}
async function totalOperators(env){const r=await env.DB.prepare(`SELECT COUNT(*) total FROM operator_profiles WHERE is_visible=1`).first();return Number(r?.total||0);}

function parsePoint(text){if(!text)return null;const s=decodeURIComponent(text.trim());try{const u=new URL(s),h=u.hostname.toLowerCase();if(h.includes("yandex")){for(const v of [u.searchParams.get("pt"),u.searchParams.get("ll")]){if(!v)continue;const parts=v.split(/[,\s]+/).map(Number);if(parts.length>=2&&validPoint(parts[1],parts[0]))return{point:point(parts[1],parts[0]),label:"Yandex Maps"};}}if(h.includes("openstreetmap")){const lat=Number(u.searchParams.get("mlat")||u.searchParams.get("lat")),lon=Number(u.searchParams.get("mlon")||u.searchParams.get("lon"));if(validPoint(lat,lon))return{point:point(lat,lon),label:"OpenStreetMap"};}const q=u.searchParams.get("q")||u.searchParams.get("query");if(q){const m=q.match(/(-?\d{1,2}(?:\.\d+)?)\s*,\s*(-?\d{1,3}(?:\.\d+)?)/);if(m){const lat=Number(m[1]),lon=Number(m[2]);if(validPoint(lat,lon))return{point:point(lat,lon),label:"Google Maps"};}}const at=s.match(/@(-?\d{1,2}(?:\.\d+)?),\s*(-?\d{1,3}(?:\.\d+)?)/);if(at){const lat=Number(at[1]),lon=Number(at[2]);if(validPoint(lat,lon))return{point:point(lat,lon),label:"map link"};}}catch{}const m=s.match(/(-?\d{1,2}(?:[.,]\d+)?)\s*[,; ]\s*(-?\d{1,3}(?:[.,]\d+)?)/);if(m){const lat=Number(m[1].replace(",",".")),lon=Number(m[2].replace(",","."));if(validPoint(lat,lon))return{point:point(lat,lon),label:"координаты"};}return null;}
async function geocode(text){const q=text.trim();if(!q||q.length<3||q.length>180)return null;const enriched=/москва|moscow/i.test(q)?q:"Москва, "+q;const r=await fetch("https://nominatim.openstreetmap.org/search?format=json&limit=1&accept-language=ru&q="+encodeURIComponent(enriched),{headers:{"User-Agent":"WanderOS Telegram bot / educational project","Accept":"application/json"}});if(!r.ok)return null;const data=await r.json();if(!Array.isArray(data)||!data.length)return null;const lat=Number(data[0].lat),lon=Number(data[0].lon);if(!validPoint(lat,lon))return null;return{point:point(lat,lon),label:data[0].display_name||enriched};}

function menu(){return `<b>WanderOS</b>\n<i>полевой терминал бюро</i>\n\n⌂ <b>Штаб</b> — база операций\n◌ <b>Сигнал</b> — метка рядом со штабом\n⟡ <b>Выход</b> — путь до сигнала\n⊕ <b>Оперативники</b> — каталог и поиск\n⚭ <b>Кооперация</b> — совместные выходы\n☾ <b>Досье</b> — профиль оператора\n‡ <b>Архив</b> — следы`;}
function operatorsMenu(total){return `<b>⊕ Оперативники</b>\n\nВсего зарегистрировано в бюро: <b>${total}</b>\n\nВыбери вкладку.`;}
function homePrompt(){return `<b>⌂ Установка штаба</b>\n\nОтправь координаты, ссылку на карту или адрес.\n\n<code>55.7558, 37.6173</code>\n<code>Тверская 13</code>`;}
function needHome(){return `<b>Штаб не установлен.</b>\n\nОткрой ⌂ <b>Штаб</b> и задай базу операций.`;}
function needReg(){return `<b>Досье не оформлено.</b>\n\nДля кооперации нужна регистрация в бюро.`;}
function homeSaved(origin,target,route,label){return `<b>⌂ Штаб установлен.</b>\n\nБаза: <code>${origin.lat}, ${origin.lon}</code>\nМетка: ${esc(label||"штаб")}\n\nПервичный сигнал: <code>${target.lat}, ${target.lon}</code>\n<a href="${urlEsc(route)}">Открыть путь</a>`;}
function profileText(p,tc,cc,rs){if(!registered(p))return `<b>☾ Досье оператора</b>\n\nСтатус: не оформлено.\n\nКоманда: <code>/register</code>`;const name=p.username?"@"+esc(p.username):esc(p.first_name||"нет");const base=hasHome(p)?`<code>${p.base_lat}, ${p.base_lon}</code>\n${esc(p.base_label||"штаб")}`:"не установлен";return `<b>☾ Досье оператора</b>\n\nПозывной: <b>${esc(p.callsign)}</b>\nПользователь: ${name}\nВозраст: ${p.age}\nПол: ${esc(p.sex)}\nЭффективность: <b>${eff(rs)}</b>\nРадиус: <b>${p.radius_m} м</b>\nШтаб: ${base}\nСледы: <b>${tc}</b>\nКооперации: <b>${cc}</b>\n\n${esc(p.bio)}`;}
function editMenuText(p){return `<b>Редактирование досье</b>\n\nПозывной: <b>${esc(p.callsign)}</b>\nВозраст: ${p.age}\nПол: ${esc(p.sex)}\nБиография: ${esc(trim(p.bio,120))}${p.bio?.length>120?"…":""}`;}
function routeMsg(kind,t,route,title,omen,id){const head=kind==="route"?`⟡ Выход: ${esc(title)}`:`◌ Сигнал: ${esc(title)}`;const link=kind==="route"?"Идти":"Открыть путь";return `<b>${head}</b>\n\n${kind==="route"?"Цель":"Метка"}: <code>${t.lat}, ${t.lon}</code>\n<a href="${urlEsc(route)}">${link}</a>\n\n<i>${esc(omen)}</i>\n\nСлед: <code>${id.slice(0,8)}</code>`;}
function radiusPrompt(){return `<b>⛯ Радиус поиска</b>\n\nНапиши число от 200 до 5000.\n\n<code>800</code>`;}
function parseRadius(text){const m=text.match(/(\d+)/);if(!m)return null;const r=Number.parseInt(m[1],10);return Number.isFinite(r)&&r>=MIN_RADIUS&&r<=MAX_RADIUS?r:null;}
function opsNearText(items,page,radius,total){if(!items.length)return `<b>⊕ Оперативники в радиусе</b>\n\nВ радиусе ${radius} м никого не найдено.\nВсего в бюро: <b>${total}</b>`;let out=`<b>⊕ Оперативники в радиусе</b>\n<i>по возрастанию дистанции</i>\nВсего в бюро: <b>${total}</b>\n\n`;items.forEach((x,i)=>out+=`<b>${i+1}.</b> ${esc(x.callsign)} · ${x.age} · ${x.distance_m} м · ${eff(x.review)}\n`);return out+`\nСтраница: ${page+1}`;}
function opsAllText(items,page,total){if(!items.length)return `<b>⊕ Все оперативники</b>\n\nКаталог пуст.`;let out=`<b>⊕ Все оперативники по эффективности</b>\nВсего в бюро: <b>${total}</b>\n\n`;items.forEach((x,i)=>out+=`<b>${page*PAGE+i+1}.</b> ${esc(x.callsign)} · ${x.age} · ${eff(x.review)}\n`);return out+`\nСтраница: ${page+1}`;}
function opSearchText(items,q){if(!items.length)return `<b>Поиск оперативника</b>\n\nПо запросу <code>${esc(q)}</code> ничего не найдено.`;let out=`<b>Поиск оперативника</b>\nЗапрос: <code>${esc(q)}</code>\n\n`;items.forEach((x,i)=>out+=`<b>${i+1}.</b> ${esc(x.callsign)} · ${x.age} · ${eff(x.review)}\n`);return out;}
function opText(op,d,tc,cc,rs,my){const u=op.username?"@"+esc(op.username):esc(op.first_name||"нет");const voted=my?`\nТвой отзыв: <b>${my.vote>0?"+":"-"}</b>`:"";const dline=Number.isFinite(d)?`\nДистанция: ${d} м`:"";return `<b>☾ Досье: ${esc(op.callsign)}</b>\n\nПользователь: ${u}\nВозраст: ${op.age}${dline}\nЭффективность: <b>${eff(rs)}</b>${voted}\nСледы: <b>${tc}</b>\nКооперации: <b>${cc}</b>\n\n${esc(op.bio)}`;}
function historyText(rows,page,owner){if(!rows.length)return `<b>‡ Архив пуст.</b>\n\nСледов ещё нет.`;let out="<b>‡ Архив следов</b>\n";if(owner)out+=`<i>${esc(owner)}</i>\n`;out+="\n";rows.forEach((r,i)=>out+=`<b>${i+1}. ${esc(r.title||"сигнал")}</b>\n<code>${r.target_lat}, ${r.target_lon}</code>\n\n`);return(out+`Страница: ${page+1}`).trim();}
function traceText(t,c,idx,count,owner){let out=`<b>‡ След: ${esc(t.title||"сигнал")}</b>\n\nОператор: ${esc(owner||"неизвестно")}\nЦель: <code>${t.target_lat}, ${t.target_lon}</code>\n<a href="${urlEsc(t.route_url)}">путь</a>\n\n`;out+=c?.summary?`<b>Сводка:</b>\n${esc(c.summary)}\n\n`:`<i>Сводка не заполнена.</i>\n\n`;if(count>0)out+=`Медиа: ${idx+1}/${count}`;return out.trim();}
function coopsText(rows){if(!rows.length)return `<b>⚭ Кооперация</b>\n\nАктивных записей нет.`;let out="<b>⚭ Кооперация</b>\n\n";rows.forEach((r,i)=>out+=`<b>${i+1}.</b> ${esc(r.name||"оператор")} · ${esc(r.status)}\n`);return out.trim();}

async function saveHome(env,ctx,chatId,origin,label,cleanup){const o=await setHome(env,chatId,origin.lat,origin.lon,label),p=await profile(env,chatId),r=p.radius_m||DEFAULT_RADIUS,target=randomPoint(o,r),title=pick(TITLES),omen=pick(OMENS),route=await addRoute(env,chatId,"home",o,target,r,title,omen);await flowClear(env,chatId);await event(env,chatId,"home_saved",{origin:o,target,label});await sendScreen(env,ctx,chatId,homeSaved(o,target,route.route,label),cleanup,{inline:ik([[{text:"‡ Открыть след",callback_data:"tr:"+route.id+":0"}],[{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function handleHomeText(env,ctx,chatId,text,cleanup){const parsed=parsePoint(text)||await geocode(text);if(parsed){await saveHome(env,ctx,chatId,parsed.point,parsed.label,cleanup);return true;}await sendScreen(env,ctx,chatId,"<b>Штаб не найден.</b>\n\nНужны координаты, ссылка на карту или точный адрес.",cleanup);return true;}
async function handleLocation(env,ctx,chatId,m,cleanup){const loc=m.location||m.venue?.location;if(!loc){await sendScreen(env,ctx,chatId,"<b>Штаб не принят.</b>",cleanup);return;}const label=m.venue?[m.venue.title,m.venue.address].filter(Boolean).join(" — "):"штаб";await saveHome(env,ctx,chatId,point(loc.latitude,loc.longitude),label,cleanup);}
async function makeRoute(env,ctx,chatId,kind,cleanup){const p=await profile(env,chatId);if(!hasHome(p)){await sendScreen(env,ctx,chatId,needHome(),cleanup);return;}const o=point(p.base_lat,p.base_lon),r=p.radius_m||DEFAULT_RADIUS,target=randomPoint(o,r),title=pick(TITLES),omen=pick(OMENS),route=await addRoute(env,chatId,kind,o,target,r,title,omen);await event(env,chatId,kind,{target,route_id:route.id});await sendScreen(env,ctx,chatId,routeMsg(kind,target,route.route,title,omen,route.id),cleanup,{inline:ik([[{text:"✎ Сводка",callback_data:"tn:"+route.id},{text:"＋ Медиа",callback_data:"tm:"+route.id}],[{text:"‡ Открыть след",callback_data:"tr:"+route.id+":0"}],[{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function showProfile(env,ctx,chatId,cleanup=[]){const p=await profile(env,chatId),tc=await countRoutes(env,chatId),cc=await countCoops(env,chatId),rs=await reviewStats(env,chatId);const buttons=registered(p)?ik([[{text:"✎ Редактировать",callback_data:"edit:menu"}],[{text:"‡ Мои следы",callback_data:"trs:"+chatId+":0"}],[{text:"⌂ Терминал",callback_data:"menu"}]]):ik([[{text:"Оформить досье",callback_data:"reg:start"}],[{text:"⌂ Терминал",callback_data:"menu"}]]);await sendScreen(env,ctx,chatId,profileText(p,tc,cc,rs),cleanup,{photo:p?.photo_file_id||null,inline:buttons});}
async function showEditMenu(env,ctx,chatId,cleanup=[]){const p=await profile(env,chatId);if(!registered(p)){await sendScreen(env,ctx,chatId,needReg(),cleanup,{inline:ik([[{text:"Оформить досье",callback_data:"reg:start"}]])});return;}await sendScreen(env,ctx,chatId,editMenuText(p),cleanup,{inline:ik([[{text:"Позывной",callback_data:"edit:callsign"},{text:"Возраст",callback_data:"edit:age"}],[{text:"Пол",callback_data:"edit:sex"},{text:"Био",callback_data:"edit:bio"}],[{text:"Фото",callback_data:"edit:photo"}],[{text:"◀ Досье",callback_data:"me"}]])});}
async function startReg(env,ctx,chatId,cleanup=[]){await flowSet(env,chatId,"reg_callsign",{});await sendScreen(env,ctx,chatId,"<b>Регистрация в бюро</b>\n\nУкажи уникальный позывной.",cleanup);}
async function finishReg(env,ctx,chatId,payload,photo,cleanup){if(await callsignTaken(env,payload.callsign,chatId)){await flowSet(env,chatId,"reg_callsign",{});await sendScreen(env,ctx,chatId,"<b>Позывной занят.</b>\n\nУкажи другой позывной.",cleanup);return;}try{await env.DB.prepare(`INSERT INTO operator_profiles(chat_id,callsign,age,sex,bio,photo_file_id,is_visible,registered_at,updated_at) VALUES(?,?,?,?,?,?,1,?,?) ON CONFLICT(chat_id) DO UPDATE SET callsign=excluded.callsign,age=excluded.age,sex=excluded.sex,bio=excluded.bio,photo_file_id=excluded.photo_file_id,is_visible=1,updated_at=excluded.updated_at`).bind(String(chatId),payload.callsign,Number(payload.age),payload.sex,payload.bio,photo||null,now(),now()).run();}catch{await flowSet(env,chatId,"reg_callsign",{});await sendScreen(env,ctx,chatId,"<b>Позывной занят.</b>\n\nУкажи другой позывной.",cleanup);return;}await flowClear(env,chatId);await sendScreen(env,ctx,chatId,`<b>Досье оформлено.</b>\n\nПозывной: <b>${esc(payload.callsign)}</b>\nСтатус: оператор бюро.`,cleanup,{inline:ik([[{text:"☾ Досье",callback_data:"me"}],[{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function updateOperatorField(env,ctx,chatId,field,value,cleanup){const p=await profile(env,chatId);if(!registered(p)){await sendScreen(env,ctx,chatId,needReg(),cleanup);return;}if(field==="callsign"){const callsign=normCallsign(value);if(!callsign||hasLink(callsign)||await callsignTaken(env,callsign,chatId)){await sendScreen(env,ctx,chatId,"<b>Позывной не принят.</b>\n\nОн пустой, содержит ссылку или уже занят.",cleanup);return;}await env.DB.prepare(`UPDATE operator_profiles SET callsign=?,updated_at=? WHERE chat_id=?`).bind(callsign,now(),String(chatId)).run();}
if(field==="age"){const age=Number.parseInt(value,10);if(!Number.isFinite(age)||age<14||age>99){await sendScreen(env,ctx,chatId,"<b>Возраст не принят.</b>\n\nДиапазон: 14–99.",cleanup);return;}await env.DB.prepare(`UPDATE operator_profiles SET age=?,updated_at=? WHERE chat_id=?`).bind(age,now(),String(chatId)).run();}
if(field==="sex"){const sex=trim(value,32);if(!sex||hasLink(sex)){await sendScreen(env,ctx,chatId,"<b>Запись не принята.</b>\n\nКоротко, без ссылок.",cleanup);return;}await env.DB.prepare(`UPDATE operator_profiles SET sex=?,updated_at=? WHERE chat_id=?`).bind(sex,now(),String(chatId)).run();}
if(field==="bio"){const bio=trim(value,512);if(!bio||hasLink(bio)){await sendScreen(env,ctx,chatId,"<b>Биография не принята.</b>\n\nДо 512 символов, без ссылок.",cleanup);return;}await env.DB.prepare(`UPDATE operator_profiles SET bio=?,updated_at=? WHERE chat_id=?`).bind(bio,now(),String(chatId)).run();}
await flowClear(env,chatId);await showEditMenu(env,ctx,chatId,cleanup);}
async function handleRegFlow(env,ctx,chatId,m,flow,cleanup){const text=msgText(m);if(flow.mode==="reg_callsign"){const callsign=normCallsign(text);if(!callsign||hasLink(callsign)||await callsignTaken(env,callsign,chatId)){await sendScreen(env,ctx,chatId,"<b>Позывной не принят.</b>\n\nДо 32 символов, без ссылок, уникальный.",cleanup);return true;}await flowSet(env,chatId,"reg_age",{callsign});await sendScreen(env,ctx,chatId,"<b>Возраст.</b>\n\nНапиши число.",cleanup);return true;}if(flow.mode==="reg_age"){const age=Number.parseInt(text,10);if(!Number.isFinite(age)||age<14||age>99){await sendScreen(env,ctx,chatId,"<b>Возраст не принят.</b>\n\nДиапазон: 14–99.",cleanup);return true;}await flowSet(env,chatId,"reg_sex",{...flow.payload,age});await sendScreen(env,ctx,chatId,"<b>Пол.</b>\n\nКороткая запись.",cleanup);return true;}if(flow.mode==="reg_sex"){const sex=trim(text,32);if(!sex||hasLink(sex)){await sendScreen(env,ctx,chatId,"<b>Запись не принята.</b>\n\nКоротко, без ссылок.",cleanup);return true;}await flowSet(env,chatId,"reg_bio",{...flow.payload,sex});await sendScreen(env,ctx,chatId,"<b>Биография.</b>\n\nДо 512 символов. Ссылки запрещены.",cleanup);return true;}if(flow.mode==="reg_bio"){const bio=trim(text,512);if(!bio||hasLink(bio)){await sendScreen(env,ctx,chatId,"<b>Биография не принята.</b>\n\nДо 512 символов, без ссылок.",cleanup);return true;}await flowSet(env,chatId,"reg_photo",{...flow.payload,bio});await sendScreen(env,ctx,chatId,"<b>Фото досье.</b>\n\nОтправь фото или <code>/skip</code>.",cleanup);return true;}if(flow.mode==="reg_photo"){const photo=bestPhoto(m);if(text==="/skip"||text.toLowerCase()==="пропустить"){await finishReg(env,ctx,chatId,flow.payload,null,cleanup);return true;}if(!photo){await sendScreen(env,ctx,chatId,"<b>Жду фото.</b>\n\nИли <code>/skip</code>.",cleanup);return true;}await finishReg(env,ctx,chatId,flow.payload,photo,cleanup);return true;}return false;}
async function handleFlow(env,ctx,chatId,m,flow,cleanup){if(!flow.mode)return false;if(flow.mode.startsWith("reg_"))return await handleRegFlow(env,ctx,chatId,m,flow,cleanup);if(flow.mode.startsWith("edit_")){const field=flow.mode.replace("edit_","");if(field==="photo"){const photo=bestPhoto(m);if(!photo){await sendScreen(env,ctx,chatId,"<b>Жду новое фото.</b>",cleanup);return true;}await env.DB.prepare(`UPDATE operator_profiles SET photo_file_id=?,updated_at=? WHERE chat_id=?`).bind(photo,now(),String(chatId)).run();await flowClear(env,chatId);await showEditMenu(env,ctx,chatId,cleanup);return true;}await updateOperatorField(env,ctx,chatId,field,msgText(m),cleanup);return true;}if(flow.mode==="search_operator"){await showSearchResults(env,ctx,chatId,msgText(m),cleanup);await flowClear(env,chatId);return true;}if(flow.mode==="await_home"){if(m.location||m.venue){await handleLocation(env,ctx,chatId,m,cleanup);return true;}return await handleHomeText(env,ctx,chatId,msgText(m),cleanup);}if(flow.mode==="await_radius"){const r=parseRadius(msgText(m));if(!r){await sendScreen(env,ctx,chatId,radiusPrompt(),cleanup);return true;}await setRadius(env,chatId,r);await flowClear(env,chatId);await sendScreen(env,ctx,chatId,`<b>Радиус изменён.</b>\n\nКруг поиска: <b>${r} м</b>.`,cleanup);return true;}if(flow.mode==="trace_note"){await setTraceSummary(env,ctx,chatId,flow.payload.route_id,msgText(m),cleanup);return true;}if(flow.mode==="trace_media"){await addTraceMedia(env,ctx,chatId,flow.payload.route_id,m,cleanup);return true;}return false;}

async function showOperatorsMenu(env,ctx,chatId,cleanup=[]){const total=await totalOperators(env);await sendScreen(env,ctx,chatId,operatorsMenu(total),cleanup,{inline:ik([[{text:"В радиусе",callback_data:"opsnear:0"},{text:"Все по рейтингу",callback_data:"opsall:0"}],[{text:"Поиск по позывному",callback_data:"opssearch"}],[{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function nearby(env,chatId,page){const self=await profile(env,chatId);if(!registered(self))return{error:"reg",items:[],radius:0,total:0};if(!hasHome(self))return{error:"home",items:[],radius:0,total:0};const origin=point(self.base_lat,self.base_lon),radius=self.radius_m||DEFAULT_RADIUS;const q=await env.DB.prepare(`SELECT op.chat_id,op.callsign,op.age,op.bio,op.photo_file_id,u.username,u.first_name,p.base_lat,p.base_lon FROM operator_profiles op JOIN users u ON u.chat_id=op.chat_id JOIN profiles p ON p.chat_id=op.chat_id WHERE op.is_visible=1 AND op.chat_id<>? AND p.base_lat IS NOT NULL AND p.base_lon IS NOT NULL LIMIT 500`).bind(String(chatId)).all();const all=[];for(const x of(q.results||[])){const dm=dist(origin,point(x.base_lat,x.base_lon));if(dm<=radius)all.push({...x,distance_m:dm,review:await reviewStats(env,x.chat_id)});}all.sort((a,b)=>a.distance_m-b.distance_m);return{items:all.slice(page*PAGE,page*PAGE+PAGE),total:all.length,radius};}
async function showOpsNear(env,ctx,chatId,page,cleanup=[]){const d=await nearby(env,chatId,page),total=await totalOperators(env);if(d.error==="reg"){await sendScreen(env,ctx,chatId,needReg(),cleanup,{inline:ik([[{text:"Оформить досье",callback_data:"reg:start"}],[{text:"◀ Оперативники",callback_data:"opsmenu"}]])});return;}if(d.error==="home"){await sendScreen(env,ctx,chatId,needHome(),cleanup,{inline:ik([[{text:"◀ Оперативники",callback_data:"opsmenu"}]])});return;}const rows=[],nums=d.items.map((x,i)=>({text:String(i+1),callback_data:"op:"+x.chat_id+":"+page+":near"}));for(let i=0;i<nums.length;i+=5)rows.push(nums.slice(i,i+5));const nav=[];if(page>0)nav.push({text:"◀",callback_data:"opsnear:"+(page-1)});if((page+1)*PAGE<d.total)nav.push({text:"▶",callback_data:"opsnear:"+(page+1)});if(nav.length)rows.push(nav);rows.push([{text:"Все",callback_data:"opsall:0"},{text:"Поиск",callback_data:"opssearch"}]);rows.push([{text:"◀ Меню оперативников",callback_data:"opsmenu"}]);await sendScreen(env,ctx,chatId,opsNearText(d.items,page,d.radius,total),cleanup,{inline:ik(rows)});}
async function allOperators(env,page){const q=await env.DB.prepare(`SELECT op.chat_id,op.callsign,op.age,op.photo_file_id,u.username,u.first_name FROM operator_profiles op JOIN users u ON u.chat_id=op.chat_id WHERE op.is_visible=1 LIMIT 500`).all();const all=[];for(const x of(q.results||[]))all.push({...x,review:await reviewStats(env,x.chat_id)});all.sort((a,b)=>(b.review.rating-a.review.rating)||(b.review.plus-a.review.plus)||a.callsign.localeCompare(b.callsign,"ru"));return{items:all.slice(page*PAGE,page*PAGE+PAGE),total:all.length};}
async function showOpsAll(env,ctx,chatId,page,cleanup=[]){const d=await allOperators(env,page);const rows=[],nums=d.items.map((x,i)=>({text:String(page*PAGE+i+1),callback_data:"op:"+x.chat_id+":"+page+":all"}));for(let i=0;i<nums.length;i+=5)rows.push(nums.slice(i,i+5));const nav=[];if(page>0)nav.push({text:"◀",callback_data:"opsall:"+(page-1)});if((page+1)*PAGE<d.total)nav.push({text:"▶",callback_data:"opsall:"+(page+1)});if(nav.length)rows.push(nav);rows.push([{text:"В радиусе",callback_data:"opsnear:0"},{text:"Поиск",callback_data:"opssearch"}]);rows.push([{text:"◀ Меню оперативников",callback_data:"opsmenu"}]);await sendScreen(env,ctx,chatId,opsAllText(d.items,page,d.total),cleanup,{inline:ik(rows)});}
async function showSearchPrompt(env,ctx,chatId,cleanup=[]){await flowSet(env,chatId,"search_operator",{});await sendScreen(env,ctx,chatId,"<b>Поиск оперативника</b>\n\nНапиши позывной или его часть.",cleanup,{inline:ik([[{text:"◀ Меню оперативников",callback_data:"opsmenu"}]])});}
async function showSearchResults(env,ctx,chatId,q,cleanup=[]){const query=trim(q,32);if(!query){await showSearchPrompt(env,ctx,chatId,cleanup);return;}const r=await env.DB.prepare(`SELECT op.chat_id,op.callsign,op.age,op.photo_file_id,u.username,u.first_name FROM operator_profiles op JOIN users u ON u.chat_id=op.chat_id WHERE op.is_visible=1 AND op.callsign LIKE ? COLLATE NOCASE ORDER BY op.callsign COLLATE NOCASE LIMIT 10`).bind("%"+query+"%").all();const items=[];for(const x of(r.results||[]))items.push({...x,review:await reviewStats(env,x.chat_id)});const rows=[];const nums=items.map((x,i)=>({text:String(i+1),callback_data:"op:"+x.chat_id+":0:search"}));for(let i=0;i<nums.length;i+=5)rows.push(nums.slice(i,i+5));rows.push([{text:"Новый поиск",callback_data:"opssearch"},{text:"◀ Меню",callback_data:"opsmenu"}]);await sendScreen(env,ctx,chatId,opSearchText(items,query),cleanup,{inline:ik(rows)});}
async function showOp(env,ctx,viewer,target,page=0,source="near",cleanup=[]){const v=await profile(env,viewer),op=await operator(env,target);if(!op){await showOperatorsMenu(env,ctx,viewer,cleanup);return;}let d=NaN;if(hasHome(v)&&typeof op.base_lat==="number")d=dist(point(v.base_lat,v.base_lon),point(op.base_lat,op.base_lon));const tc=await countRoutes(env,target),cc=await countCoops(env,target),rs=await reviewStats(env,target),mine=await myReview(env,viewer,target);let back="opsmenu";if(source==="near")back="opsnear:"+page;if(source==="all")back="opsall:"+page;if(source==="search")back="opssearch";await sendScreen(env,ctx,viewer,opText(op,d,tc,cc,rs,mine),cleanup,{photo:op.photo_file_id||null,inline:ik([[{text:"＋ эффективность",callback_data:"rv:"+target+":1"},{text:"− эффективность",callback_data:"rv:"+target+":-1"}],[{text:"⚭ Запросить кооперацию",callback_data:"coop:"+target}],[{text:"‡ Следы",callback_data:"trs:"+target+":0"}],[{text:"◀ Назад",callback_data:back},{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function reviewOperator(env,ctx,reviewer,target,vote){const me=await profile(env,reviewer),op=await operator(env,target);if(String(reviewer)===String(target)){await sendScreen(env,ctx,reviewer,"<b>Отзыв отклонён.</b>\n\nНельзя оценивать собственную эффективность.");return;}if(!registered(me)||!op){await sendScreen(env,ctx,reviewer,needReg());return;}const ex=await myReview(env,reviewer,target);if(ex){await sendScreen(env,ctx,reviewer,`<b>Отзыв уже учтён.</b>\n\nОдин оператор может оценить другого только один раз.\nТвой знак: <b>${ex.vote>0?"+":"-"}</b>`);return;}await setReview(env,reviewer,target,Number(vote)>0?1:-1);const rs=await reviewStats(env,target);await sendScreen(env,ctx,reviewer,`<b>Эффективность обновлена.</b>\n\nОператор: <b>${esc(op.callsign)}</b>\nТекущий рейтинг: <b>${eff(rs)}</b>`,[],{inline:ik([[{text:"☾ Открыть досье",callback_data:"op:"+target+":0:all"}],[{text:"⌂ Терминал",callback_data:"menu"}]])});}
async function coopRequest(env,ctx,from,to,cleanup=[]){const a=await profile(env,from),b=await operator(env,to);if(!registered(a)||!b){await sendScreen(env,ctx,from,needReg(),cleanup);return;}const ex=await env.DB.prepare(`SELECT id,status FROM cooperations WHERE ((requester_chat_id=? AND target_chat_id=?) OR (requester_chat_id=? AND target_chat_id=?)) AND status IN ('pending','accepted') LIMIT 1`).bind(String(from),String(to),String(to),String(from)).first();if(ex){await sendScreen(env,ctx,from,`<b>⚭ Канал уже открыт.</b>\n\nСтатус: ${esc(ex.status)}`,cleanup);return;}const id=uid();await env.DB.prepare(`INSERT INTO cooperations(id,requester_chat_id,target_chat_id,status,created_at,updated_at) VALUES(?,?,?,'pending',?,?)`).bind(id,String(from),String(to),now(),now()).run();await sendScreen(env,ctx,from,"<b>⚭ Запрос отправлен.</b>\n\nОжидание ответа оператора.",cleanup);await sendScreen(env,ctx,to,`<b>⚭ Запрос кооперации</b>\n\nОператор: <b>${esc(a.callsign)}</b>\n\nСовместный выход требует подтверждения.`,[],{photo:a.photo_file_id||null,inline:ik([[{text:"Принять",callback_data:"ca:"+id},{text:"Отклонить",callback_data:"cd:"+id}]])});}
async function answerCoop(env,ctx,chatId,id,status){const c=await env.DB.prepare(`SELECT * FROM cooperations WHERE id=?`).bind(id).first();if(!c||String(c.target_chat_id)!==String(chatId)){await sendScreen(env,ctx,chatId,"<b>Канал не найден.</b>");return;}await env.DB.prepare(`UPDATE cooperations SET status=?,updated_at=? WHERE id=?`).bind(status,now(),id).run();const target=await operator(env,c.target_chat_id);if(status==="accepted"){await sendScreen(env,ctx,chatId,"<b>⚭ Кооперация подтверждена.</b>\n\nКанал открыт.");await sendScreen(env,ctx,c.requester_chat_id,`<b>⚭ Кооперация подтверждена.</b>\n\nОператор: <b>${esc(target?.callsign||"оператор")}</b>`);}else{await sendScreen(env,ctx,chatId,"<b>Запрос отклонён.</b>");await sendScreen(env,ctx,c.requester_chat_id,`<b>⚭ Запрос не принят.</b>\n\nОператор: <b>${esc(target?.callsign||"оператор")}</b>`);}}
async function showCoops(env,ctx,chatId,cleanup=[]){const q=await env.DB.prepare(`SELECT c.status,CASE WHEN c.requester_chat_id=? THEN op2.callsign ELSE op1.callsign END AS name FROM cooperations c LEFT JOIN operator_profiles op1 ON op1.chat_id=c.requester_chat_id LEFT JOIN operator_profiles op2 ON op2.chat_id=c.target_chat_id WHERE c.requester_chat_id=? OR c.target_chat_id=? ORDER BY c.updated_at DESC LIMIT 10`).bind(String(chatId),String(chatId),String(chatId)).all();await sendScreen(env,ctx,chatId,coopsText(q.results||[]),cleanup,{inline:ik([[{text:"⌂ Терминал",callback_data:"menu"}]])});}

async function showTraceList(env,ctx,viewer,owner,page,cleanup=[]){const op=await operator(env,owner),rs=await routes(env,owner,page),rows=[];const nums=rs.map((r,i)=>({text:String(i+1),callback_data:"tr:"+r.id+":0"}));for(let i=0;i<nums.length;i+=5)rows.push(nums.slice(i,i+5));const nav=[];if(page>0)nav.push({text:"◀",callback_data:"trs:"+owner+":"+(page-1)});if(rs.length===PAGE)nav.push({text:"▶",callback_data:"trs:"+owner+":"+(page+1)});if(nav.length)rows.push(nav);rows.push([{text:"⌂ Терминал",callback_data:"menu"}]);await sendScreen(env,ctx,viewer,historyText(rs,page,op?.callsign||null),cleanup,{inline:ik(rows)});}
async function getTrace(env,id){return await env.DB.prepare(`SELECT r.*,op.callsign FROM routes r LEFT JOIN operator_profiles op ON op.chat_id=r.chat_id WHERE r.id=?`).bind(id).first();}
async function getCard(env,id){return await env.DB.prepare(`SELECT * FROM trace_cards WHERE route_id=?`).bind(id).first();}
async function getMedia(env,id){const r=await env.DB.prepare(`SELECT * FROM trace_media WHERE route_id=? ORDER BY position ASC`).bind(id).all();return r.results||[];}
async function showTrace(env,ctx,viewer,id,mediaIndex=0,cleanup=[]){const tr=await getTrace(env,id);if(!tr){await sendScreen(env,ctx,viewer,"<b>След не найден.</b>",cleanup);return;}const card=await getCard(env,id),media=await getMedia(env,id),idx=Math.max(0,Math.min(Number(mediaIndex||0),Math.max(0,media.length-1))),cur=media[idx]||null,owner=String(tr.chat_id)===String(viewer);const buttons=[];if(media.length>1)buttons.push([{text:"◀ Медиа",callback_data:"tr:"+id+":"+(idx>0?idx-1:media.length-1)},{text:"▶ Медиа",callback_data:"tr:"+id+":"+(idx<media.length-1?idx+1:0)}]);if(owner)buttons.push([{text:"✎ Сводка",callback_data:"tn:"+id},{text:"＋ Медиа",callback_data:"tm:"+id}]);buttons.push([{text:"‡ Архив",callback_data:"trs:"+tr.chat_id+":0"}]);const opt={inline:ik(buttons)};if(cur?.media_type==="photo")opt.photo=cur.file_id;if(cur?.media_type==="video")opt.video=cur.file_id;await sendScreen(env,ctx,viewer,traceText(tr,card,idx,media.length,tr.callsign),cleanup,opt);}
async function setTraceSummary(env,ctx,chatId,id,text,cleanup){const tr=await getTrace(env,id);if(!tr||String(tr.chat_id)!==String(chatId)){await sendScreen(env,ctx,chatId,"<b>След не найден.</b>",cleanup);return;}const summary=trim(text,512);if(!summary||hasLink(summary)){await sendScreen(env,ctx,chatId,"<b>Сводка не принята.</b>\n\nДо 512 символов, без ссылок.",cleanup);return;}await env.DB.prepare(`INSERT INTO trace_cards(route_id,chat_id,summary,updated_at) VALUES(?,?,?,?) ON CONFLICT(route_id) DO UPDATE SET summary=excluded.summary,updated_at=excluded.updated_at`).bind(id,String(chatId),summary,now()).run();await flowClear(env,chatId);await showTrace(env,ctx,chatId,id,0,cleanup);}
async function addTraceMedia(env,ctx,chatId,id,m,cleanup){const tr=await getTrace(env,id);if(!tr||String(tr.chat_id)!==String(chatId)){await sendScreen(env,ctx,chatId,"<b>След не найден.</b>",cleanup);return;}const media=await getMedia(env,id),hasVideo=media.some(x=>x.media_type==="video"),photo=bestPhoto(m),video=m.video||null;if(photo){if(hasVideo||media.length>=3){await sendScreen(env,ctx,chatId,"<b>Медиа не принято.</b>\n\nДо 3 фото или одно видео.",cleanup);return;}await env.DB.prepare(`INSERT INTO trace_media(id,route_id,chat_id,media_type,file_id,duration,position,created_at) VALUES(?,?,?,'photo',?,NULL,?,?)`).bind(uid(),id,String(chatId),photo,media.length+1,now()).run();await showTrace(env,ctx,chatId,id,media.length,cleanup);return;}if(video){if(media.length>0||Number(video.duration||0)>15){await sendScreen(env,ctx,chatId,"<b>Видео не принято.</b>\n\nТолько одно видео до 15 секунд.",cleanup);return;}await env.DB.prepare(`INSERT INTO trace_media(id,route_id,chat_id,media_type,file_id,duration,position,created_at) VALUES(?,?,?,'video',?,?,1,?)`).bind(uid(),id,String(chatId),video.file_id,Number(video.duration||0),now()).run();await showTrace(env,ctx,chatId,id,0,cleanup);return;}await sendScreen(env,ctx,chatId,"<b>Жду медиа.</b>\n\nФото до 3 штук или одно видео до 15 секунд.",cleanup);}

async function handleMessage(request,env,ctx){const update=await request.json();if(update.callback_query)return await handleCallback(update.callback_query,env,ctx);await ensureDirectorySchema(env);const m=update.message||update.edited_message;if(!m?.chat?.id)return new Response("ignored",{status:200});const chatId=await upsertUser(env,m),cmd=commandOf(m),text=msgText(m),incoming=m.message_id?Number(m.message_id):null,cleanup=incoming?[incoming]:[];if(incoming)await remember(env,chatId,incoming,"user");if(cmd==="/wipe"||cmd==="/clean"){const ids=await known(env,chatId,80);await clearUi(env,chatId);await flowClear(env,chatId);await sendScreen(env,ctx,chatId,menu(),cleanup.concat(ids));return new Response("ok",{status:200});}if(cmd==="/start"||cmd==="/menu"||cmd==="/help"){await flowClear(env,chatId);await sendScreen(env,ctx,chatId,menu(),cleanup);return new Response("ok",{status:200});}if(cmd==="/register"){await startReg(env,ctx,chatId,cleanup);return new Response("ok",{status:200});}if(cmd==="/sethome"||cmd==="/home"||cmd==="/location"){await flowSet(env,chatId,"await_home",{});await sendScreen(env,ctx,chatId,homePrompt(),cleanup);return new Response("ok",{status:200});}if(cmd==="/profile"){await flowClear(env,chatId);await showProfile(env,ctx,chatId,cleanup);return new Response("ok",{status:200});}if(cmd==="/operators"){await flowClear(env,chatId);await showOperatorsMenu(env,ctx,chatId,cleanup);return new Response("ok",{status:200});}if(cmd==="/coops"){await flowClear(env,chatId);await showCoops(env,ctx,chatId,cleanup);return new Response("ok",{status:200});}if(cmd==="/point"){await flowClear(env,chatId);await makeRoute(env,ctx,chatId,"point",cleanup);return new Response("ok",{status:200});}if(cmd==="/route"){await flowClear(env,chatId);await makeRoute(env,ctx,chatId,"route",cleanup);return new Response("ok",{status:200});}if(cmd==="/history"){await flowClear(env,chatId);await showTraceList(env,ctx,chatId,chatId,0,cleanup);return new Response("ok",{status:200});}if(cmd==="/report"){const p=await profile(env,chatId),c=await countRoutes(env,chatId),rs=await reviewStats(env,chatId);await sendScreen(env,ctx,chatId,`<b>Архив WanderOS</b>\n\nШтаб: ${hasHome(p)?"установлен":"нет"}\nРадиус: ${p.radius_m} м\nСледов в базе: ${c}\nЭффективность: ${eff(rs)}\n\n<i>архив содержит рабочие следы</i>`,cleanup);return new Response("ok",{status:200});}if(cmd==="/clearhome"){await flowClear(env,chatId);await env.DB.prepare(`UPDATE profiles SET base_lat=NULL,base_lon=NULL,base_label=NULL,updated_at=? WHERE chat_id=?`).bind(now(),String(chatId)).run();await sendScreen(env,ctx,chatId,"<b>Штаб сброшен.</b>\n\nПривязка удалена.",cleanup);return new Response("ok",{status:200});}if(cmd==="/radius"){const r=parseRadius(text);if(!r){await flowSet(env,chatId,"await_radius",{});await sendScreen(env,ctx,chatId,radiusPrompt(),cleanup);return new Response("ok",{status:200});}await setRadius(env,chatId,r);await flowClear(env,chatId);await sendScreen(env,ctx,chatId,`<b>Радиус изменён.</b>\n\nКруг поиска: <b>${r} м</b>.`,cleanup);return new Response("ok",{status:200});}const flow=await flowGet(env,chatId);if(flow.mode){const ok=await handleFlow(env,ctx,chatId,m,flow,cleanup);if(ok)return new Response("ok",{status:200});}if(m.location||m.venue){await handleLocation(env,ctx,chatId,m,cleanup);return new Response("ok",{status:200});}const parsed=parsePoint(text);if(parsed){await saveHome(env,ctx,chatId,parsed.point,parsed.label,cleanup);return new Response("ok",{status:200});}await sendScreen(env,ctx,chatId,menu(),cleanup);return new Response("ok",{status:200});}
async function handleCallback(cb,env,ctx){await ensureDirectorySchema(env);await tg(env,"answerCallbackQuery",{callback_query_id:cb.id});const chatId=await upsertUser(env,cb),data=cb.data||"";if(data==="menu"){await flowClear(env,chatId);await sendScreen(env,ctx,chatId,menu());return new Response("ok",{status:200});}if(data==="me"){await flowClear(env,chatId);await showProfile(env,ctx,chatId);return new Response("ok",{status:200});}if(data==="edit:menu"){await showEditMenu(env,ctx,chatId);return new Response("ok",{status:200});}if(data.startsWith("edit:")){const f=data.split(":")[1];await flowSet(env,chatId,"edit_"+f,{});const labels={callsign:"новый уникальный позывной",age:"новый возраст",sex:"новую запись пола",bio:"новую биографию до 512 символов без ссылок",photo:"новое фото"};await sendScreen(env,ctx,chatId,`<b>Редактирование</b>\n\nОтправь ${labels[f]||"новое значение"}.`);return new Response("ok",{status:200});}if(data==="reg:start"){await startReg(env,ctx,chatId,[]);return new Response("ok",{status:200});}if(data==="opsmenu"){await flowClear(env,chatId);await showOperatorsMenu(env,ctx,chatId);return new Response("ok",{status:200});}if(data.startsWith("opsnear:")){await showOpsNear(env,ctx,chatId,Number(data.split(":")[1]||0));return new Response("ok",{status:200});}if(data.startsWith("opsall:")){await showOpsAll(env,ctx,chatId,Number(data.split(":")[1]||0));return new Response("ok",{status:200});}if(data==="opssearch"){await showSearchPrompt(env,ctx,chatId);return new Response("ok",{status:200});}if(data.startsWith("op:")){const p=data.split(":");await showOp(env,ctx,chatId,p[1],Number(p[2]||0),p[3]||"near");return new Response("ok",{status:200});}if(data.startsWith("rv:")){const p=data.split(":");await reviewOperator(env,ctx,chatId,p[1],Number(p[2]||0));return new Response("ok",{status:200});}if(data.startsWith("coop:")){await coopRequest(env,ctx,chatId,data.split(":")[1]);return new Response("ok",{status:200});}if(data.startsWith("ca:")){await answerCoop(env,ctx,chatId,data.split(":")[1],"accepted");return new Response("ok",{status:200});}if(data.startsWith("cd:")){await answerCoop(env,ctx,chatId,data.split(":")[1],"declined");return new Response("ok",{status:200});}if(data.startsWith("trs:")){const p=data.split(":");await showTraceList(env,ctx,chatId,p[1],Number(p[2]||0));return new Response("ok",{status:200});}if(data.startsWith("tr:")){const p=data.split(":");await showTrace(env,ctx,chatId,p[1],Number(p[2]||0));return new Response("ok",{status:200});}if(data.startsWith("tn:")){const id=data.split(":")[1];await flowSet(env,chatId,"trace_note",{route_id:id});await sendScreen(env,ctx,chatId,"<b>Сводка следа.</b>\n\nДо 512 символов. Ссылки запрещены.");return new Response("ok",{status:200});}if(data.startsWith("tm:")){const id=data.split(":")[1];await flowSet(env,chatId,"trace_media",{route_id:id});await sendScreen(env,ctx,chatId,"<b>Медиа следа.</b>\n\nДо 3 фото или одно видео до 15 секунд.");return new Response("ok",{status:200});}await sendScreen(env,ctx,chatId,menu());return new Response("ok",{status:200});}

export default {async fetch(request,env,ctx){const url=new URL(request.url);if(url.pathname==="/"){let database="missing";try{if(env.DB){await ensureDirectorySchema(env);await env.DB.prepare("SELECT 1 AS ok").first();database="D1 ready";}}catch{database="D1 error";}return Response.json({service:"WanderOS",status:"ok",runtime:"Cloudflare Workers",database,modules:["operator-directory","nearby-operators","operator-search","profile-editing","operator-efficiency","cooperation","trace-cards","trace-media"]});}if(url.pathname!=="/webhook")return new Response("not found",{status:404});if(request.method!=="POST")return new Response("method not allowed",{status:405});if(!env.TELEGRAM_BOT_TOKEN)return new Response("missing token",{status:500});if(!env.DB)return new Response("missing D1 binding DB",{status:500});return handleMessage(request,env,ctx);}};